def compute(vars):
    crude_pipeline_miles = vars["v1"]
    refined_products_pipeline_miles = vars["v2"]
    total_miles = crude_pipeline_miles + refined_products_pipeline_miles

    return {
        "value": total_miles,
        "trace": {
            "crude_pipeline_miles": crude_pipeline_miles,
            "refined_products_pipeline_miles": refined_products_pipeline_miles,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "miles"
            }
        }
    }
